def option1_cost(n):
    return sum(int(digit) for digit in str(n))

def option2_cost(n):
    return sum(int(digit) for digit in bin(n)[2:])

def find_largest_same_cost():
    for number in range(999, 0, -1):
        if option1_cost(number) == option2_cost(number):
            return number

largest_number = find_largest_same_cost()
